"""Generate the committed OpenAPI snapshot and a small typed TS client from the app."""

from __future__ import annotations

import json
import sys
from importlib import import_module
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
API_ROOT = ROOT / "apps" / "api"
sys.path.insert(0, str(API_ROOT))

app = import_module("local_drama.main").app
API_CONTRACT_VERSION = import_module("local_drama.api.contract_version").API_CONTRACT_VERSION


def render_client_source() -> str:
    """Render the committed TS client. Static: it never depends on the live OpenAPI object."""
